void main() {
  // Example graph represented as an adjacency matrix
  // 0: no direct connection
  final graph = [
    [0, 4, 0, 0, 0, 0, 0, 8, 0],
    [4, 0, 8, 0, 0, 0, 0, 11, 0],
    [0, 8, 0, 7, 0, 4, 0, 0, 2],
    [0, 0, 7, 0, 9, 14, 0, 0, 0],
    [0, 0, 0, 9, 0, 10, 0, 0, 0],
    [0, 0, 4, 14, 10, 0, 2, 0, 0],
    [0, 0, 0, 0, 0, 2, 0, 1, 6],
    [8, 11, 0, 0, 0, 0, 1, 0, 7],
    [0, 0, 2, 0, 0, 0, 6, 7, 0]
  ];

  final startNode = 0;
  final distances = dijkstra(graph, startNode);

  print('Shortest distances from node $startNode:');
  for (var i = 0; i < distances.length; i++) {
    print('Node $i: ${distances[i]}');
  }
}

List<int> dijkstra(List<List<int>> graph, int src) {
  final n = graph.length;
  final dist = List<int>.filled(n, 999999); // Large number representing infinity
  final visited = List<bool>.filled(n, false);

  dist[src] = 0;

  for (var count = 0; count < n - 1; count++) {
    final u = minDistance(dist, visited);
    visited[u] = true;

    for (var v = 0; v < n; v++) {
      if (!visited[v] &&
          graph[u][v] != 0 &&
          dist[u] != 999999 &&
          dist[u] + graph[u][v] < dist[v]) {
        dist[v] = dist[u] + graph[u][v];
      }
    }
  }

  return dist;
}

int minDistance(List<int> dist, List<bool> visited) {
  var min = 999999;
  var minIndex = -1;

  for (var v = 0; v < dist.length; v++) {
    if (!visited[v] && dist[v] <= min) {
      min = dist[v];
      minIndex = v;
    }
  }

  return minIndex;
}
